&lt;/td&gt;
    &lt;/tr&gt;
    &lt;tr&gt;&lt;td&gt;&lt;b&gt;Inquisitions&lt;/b&gt;&lt;/td&gt;
        &lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#HERESIE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;H&#233;r&#233;sie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#PECHE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;P&#233;ch&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#PERSEVERANCE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Pers&#233;v&#233;rance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#POSSESSION&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Possession&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisitions.html#VENGEANCE&quot; title=&quot;Les inquisitions d&amp;#39;inquisiteur&quot;&gt;Vengeance&lt;/a&gt;&lt;/td&gt;
